package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipException;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_getNextZipEntry_TriageGen2Test {

    private static final long LFH_SIG = 0x04034b50L;
    private static final long CFH_SIG = 0x02014b50L;
    private static final long AED_SIG = 0x06054b50L;

    /**
     * Helper to build a valid LFH byte array for testing.
     */
    private byte[] createLFH(String name, boolean hasDataDescriptor, int method, long compressedSize, long crc, long uncompressedSize) {
        byte[] nameBytes = name.getBytes();
        int extraLen = 0;
        int totalSize = 30; // Base LFH size before name and extra
        if (hasDataDescriptor) {
            totalSize += 12; // Data descriptor size
        }
        totalSize += 2 + 2 + nameBytes.length + extraLen;

        ByteBuffer bb = ByteBuffer.allocate(totalSize).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(LFH_SIG);
        bb.putShort((short) 20); // version made by
        bb.putShort((short) 0);  // flags
        bb.putShort((short) method);
        bb.putInt(0);            // time
        bb.putInt(0);            // date

        if (!hasDataDescriptor) {
            bb.putInt((int) crc);
            bb.putInt((int) compressedSize);
            bb.putInt((int) uncompressedSize);
        }

        bb.putShort((short) nameBytes.length);
        bb.putShort((short) extraLen);
        bb.put(nameBytes);

        if (hasDataDescriptor) {
            bb.putInt((int) crc);
            bb.putInt((int) compressedSize);
            bb.putInt((int) uncompressedSize);
        }

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_Success() throws IOException {
        byte[] lfh = createLFH("test.txt", false, ZipMethod.STORED.getCode(), 4, 0x12345678L, 4);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("test.txt", entry.getName());
        Assert.assertEquals(4, entry.getCompressedSize());
        Assert.assertEquals(0x12345678L, entry.getCrc());
    }

    @Test
    public void testGetNextZipEntry_WithDataDescriptor() throws IOException {
        byte[] lfh = createLFH("data.bin", true, ZipMethod.STORED.getCode(), 8, 0xABCDEF01L, 8);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("data.bin", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNull(entry);
    }

    @Test
    public void testGetNextZipEntry_UnexpectedSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(0xBAD0BAD0L);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        try {
            zis.getNextZipEntry();
            Assert.fail("Should have thrown ZipException");
        } catch (ZipException e) {
            Assert.assertTrue(e.getMessage().contains("Unexpected record signature"));
        }
    }

    @Test
    public void testGetNextZipEntry_CentralDirectoryHit() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(CFH_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNull(entry);
    }

    @Test
    public void testGetNextZipEntry_AEDSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putLong(AED_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNull(entry);
    }

    @Test
    public void testGetNextZipEntry_ConsecutiveEntries() throws IOException {
        byte[] lfh1 = createLFH("1.txt", false, ZipMethod.STORED.getCode(), 1, 1, 1);
        byte[] lfh2 = createLFH("2.txt", false, ZipMethod.STORED.getCode(), 2, 2, 2);

        ByteBuffer bb = ByteBuffer.allocate(lfh1.length + lfh2.length);
        bb.put(lfh1);
        bb.put(lfh2);

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry e1 = zis.getNextZipEntry();
        Assert.assertNotNull(e1);
        Assert.assertEquals("1.txt", e1.getName());

        ZipArchiveEntry e2 = zis.getNextZipEntry();
        Assert.assertNotNull(e2);
        Assert.assertEquals("2.txt", e2.getName());

        ZipArchiveEntry e3 = zis.getNextZipEntry();
        Assert.assertNull(e3);
    }

    @Test
    public void testGetNextZipEntry_UnshrinkingMethod() throws IOException {
        // Test the branch for UnshrinkingInputStream
        byte[] lfh = createLFH("unshrink.txt", false, ZipMethod.UNSHRINKING.getCode(), 10, 10, 10);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals(ZipMethod.UNSHRINKING.getCode(), entry.getMethod());
    }

    @Test
    public void testGetNextZipEntry_BZip2Method() throws IOException {
        // Test the branch for BZip2CompressorInputStream
        byte[] lfh = createLFH("bzip2.txt", false, ZipMethod.BZIP2.getCode(), 10, 10, 10);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals(ZipMethod.BZIP2.getCode(), entry.getMethod());
    }
}
